export const LZ4_MAGIC=[229,161,237,254];export function hasMagic(bytes,pos=0){return bytes.length>=pos+4&&bytes[pos]===LZ4_MAGIC[0]&&bytes[pos+1]===LZ4_MAGIC[1]&&bytes[pos+2]===LZ4_MAGIC[2]&&bytes[pos+3]===LZ4_MAGIC[3]}export function lz4DecompressBlock(src,destSize){const dst=new Uint8Array(destSize);let si=0;let di=0;const slen=src.length;while(si<slen){const token=src[si++];let litLen=token>>>4;if(litLen===15){let b;do{if(si>=slen){throw new Error("LZ4: truncated literal length")}b=src[si++];litLen+=b}while(b===255)}if(litLen>0){if(di+litLen>destSize){throw new Error("LZ4: literal exceeds destination size")}if(si+litLen>slen){throw new Error("LZ4: literal overruns source")}dst.set(src.subarray(si,si+litLen),di);si+=litLen;di+=litLen}if(si>=slen){break}if(si+1>=slen){throw new Error("LZ4: truncated match offset")}const offset=src[si]|src[si+1]<<8;si+=2;if(offset===0){throw new Error("LZ4: invalid offset 0")}let matchLen=(token&15)+4;if((token&15)===15){let b;do{if(si>=slen){throw new Error("LZ4: truncated match length")}b=src[si++];matchLen+=b}while(b===255)}let mi=di-offset;if(mi<0){throw new Error("LZ4: offset before buffer start")}if(di+matchLen>destSize){throw new Error("LZ4: match exceeds destination size")}for(let i=0;i<matchLen;i++){dst[di++]=dst[mi++]}}if(di!==destSize){throw new Error(`LZ4: decompressed size ${di} != expected ${destSize}`)}return dst}function readU32le(bytes,pos){return(bytes[pos]|bytes[pos+1]<<8|bytes[pos+2]<<16|bytes[pos+3]<<24)>>>0}import{MAX_CHUNK_DECOMP_BYTES,MAX_TOTAL_DECOMP_BYTES,MAX_CHUNKS}from"./limits.min.js";export function decodeChunks(bytes){const parts=[];let total=0;let pos=0;let chunks=0;while(pos<bytes.length&&hasMagic(bytes,pos)){const compSize=readU32le(bytes,pos+4);const decompSize=readU32le(bytes,pos+8);pos+=16;if(compSize===0||pos+compSize>bytes.length||decompSize===0||decompSize>MAX_CHUNK_DECOMP_BYTES||++chunks>MAX_CHUNKS||total+decompSize>MAX_TOTAL_DECOMP_BYTES){throw new Error("LZ4: incoherent chunk header or aberrant volume, not an NMS save")}const chunk=bytes.subarray(pos,pos+compSize);pos+=compSize;const out=lz4DecompressBlock(chunk,decompSize);parts.push(out);total+=out.length}let joined=new Uint8Array(total);let off=0;for(const p of parts){joined.set(p,off);off+=p.length}let end=joined.length;while(end>0&&joined[end-1]===0){end--}return joined.subarray(0,end)}
